const URLS = {};
/** URL gambar logo (dibuat sekali per bank dan dipakai ulang), atau null bila belum ada logonya. */
export function logoUrl(kode) {
  const l = LOGOS[kode];
  if (!l) return null;
  if (!URLS[kode]) {
    URLS[kode] = typeof Blob !== 'undefined' && typeof URL?.createObjectURL === 'function'
      ? URL.createObjectURL(new Blob([l.svg], { type: 'image/svg+xml' }))
      : `data:image/svg+xml;charset=utf-8,${encodeURIComponent(l.svg)}`;
  }
  return URLS[kode];
}
